add("der-urticaria-vasculitis", [
mcq("bk2-der-111", "Migratory intensely itchy wheals that each fade within hours without bruising suggest?", ["Acute urticaria", "Urticarial vasculitis", "Erythema multiforme", "Dermatitis herpetiformis"], 0, "Urticaria wheals are transient oedematous papules resolving within a day; painful lesions beyond 24 hours with purpura suggest vasculitis.", ["Correct. Fleeting itchy wheals.", "Incorrect. That leaves bruises and pain.", "Incorrect. That gives fixed acral targets.", "Incorrect. That gives grouped extensor vesicles."], "Fleeting itchy wheals mean urticaria."),
mcq("bk2-der-112", "Linear wheals after scratching or tight clothing in a dermographic patient demonstrate?", ["Dermatographism", "Koebner phenomenon", "Nikolsky sign", "Auspitz sign"], 0, "Dermatographism is physical urticaria where stroking raises linear wheals within minutes.", ["Correct. Stroke-induced linear wheals.", "Incorrect. That plants disease lesions at trauma.", "Incorrect. That shears blistered skin.", "Incorrect. That bleeds psoriatic scale."], "Stroked linear wheals mean dermatographism."),
mcq("bk2-der-113", "Small pinpoint wheals with surrounding redness during exercise and hot showers indicate?", ["Cholinergic urticaria", "Cold urticaria", "Solar urticaria", "Pressure urticaria"], 0, "Cholinergic urticaria triggers tiny wheals with heat, sweat and exertion from acetylcholine-linked mast-cell release.", ["Correct. Exercise-heat micropapular wheals.", "Incorrect. That follows cold exposure.", "Incorrect. That follows sun within minutes.", "Incorrect. That swells hours after pressure."], "Exercise-heat wheals mean cholinergic urticaria."),
mcq("bk2-der-114", "Painful burning wheals lasting over a day and healing with brown marks plus joint pains suggest?", ["Urticarial vasculitis", "Chronic spontaneous urticaria", "Papular urticaria", "Sweet syndrome"], 0, "Urticarial vasculitis holds lesions beyond 24 hours with pain, purpura and hypocomplementemia, needing biopsy proof.", ["Correct. Painful persistent wheals with bruises.", "Incorrect. That stays itchy and fleeting.", "Incorrect. That clusters on exposed bites.", "Incorrect. That gives juicy plaques with fever."], "Painful day-long wheals mean urticarial vasculitis."),
mcq("bk2-der-115", "Palpable purpuric papules on buttocks and legs with colicky pain and haematuria in a child indicate?", ["IgA vasculitis Henoch-Schonlein", "Idiopathic thrombocytopenic purpura", "Urticarial vasculitis", "Polyarteritis nodosa"], 0, "HSP is childhood IgA small-vessel vasculitis with palpable purpura, arthritis, abdominal pain and nephritis.", ["Correct. Purpura with belly pain and blood urine.", "Incorrect. That gives non-palpable petechiae with low platelets.", "Incorrect. That gives wheals, not purpura.", "Incorrect. That nodules medium vessels in adults."], "Purpura with belly pain in a child is HSP."),
mcq("bk2-der-116", "First-line systemic control for chronic spontaneous urticaria uses?", ["Second-generation antihistamines with trigger avoidance", "Systemic antibiotics", "Topical antifungals", "Oral retinoids"], 0, "Non-sedating antihistamines control most chronic urticaria; refractory cases step to specialist immunomodulators.", ["Correct. Antihistamine backbone first.", "Incorrect. Bacteria do not drive wheals.", "Incorrect. Fungi do not drive wheals.", "Incorrect. Retinoids treat keratinisation."], "Chronic hives start with antihistamines."),
mcq("bk2-der-117", "Wheals with lip and tongue swelling plus breathlessness after a peanut meal is managed first by?", ["Intramuscular adrenaline with airway care", "Oral antihistamine alone", "Topical steroid alone", "Reassurance at home"], 0, "Anaphylaxis with airway or circulation threat needs immediate adrenaline and emergency care, not antihistamines alone.", ["Correct. Adrenaline first for anaphylaxis.", "Incorrect. Too slow for airway swelling.", "Incorrect. Topicals miss systemic collapse.", "Incorrect. Home waiting can be fatal."], "Breathless swollen airway needs adrenaline."),
mcq("bk2-der-118", "Cold-induced wheals confirmed by an ice-cube test that resolve with warming suggest?", ["Cold urticaria", "Cholinergic urticaria", "Erythema ab igne", "Raynaud phenomenon"], 0, "Cold urticaria reproduces wheals on rewarming after cold contact; swimming needs caution for systemic release.", ["Correct. Ice-cube wheals.", "Incorrect. That follows heat and sweat.", "Incorrect. That reticulates from chronic heat.", "Incorrect. That blanches digits trifasically."], "Ice-cube wheals mean cold urticaria."),
mcq("bk2-der-119", "Biopsy of a persistent wheal showing vessel-wall damage with red-cell extravasation confirms?", ["Leukocytoclastic vasculitis", "Simple dermal oedema", "Mast-cell hyperplasia alone", "Interface dermatitis"], 0, "Leukocytoclasis with nuclear dust and extravasated red cells marks small-vessel vasculitis, not simple urticaria.", ["Correct. Vessel damage with nuclear dust.", "Incorrect. That is plain urticaria histology.", "Incorrect. That marks mastocytosis.", "Incorrect. That marks lichenoid disease."], "Nuclear dust in vessel walls is vasculitis."),
mcq("bk2-der-120", "Recurrent angioedema without wheals with low C4 and family history suggests?", ["Hereditary angioedema from C1-esterase deficiency", "Allergic angioedema", "Hypothyroid puffiness", "Superior vena cava obstruction"], 0, "Hereditary angioedema gives episodic non-pitting swelling without urticaria from bradykinin via C1-inhibitor lack.", ["Correct. Familial wheal-free swelling with low C4.", "Incorrect. That pairs with wheals and itch.", "Incorrect. That is persistent and doughy.", "Incorrect. That congests face with collaterals."], "Familial wheal-free swelling is hereditary angioedema.")]);

