const SUBJECT = "dermatology";
const SUBJECT_DIR = path.join(ROOT, "prep/overlays/maikbook2", SUBJECT);
const KB_DIR = path.join(ROOT, "kb/reference");
const LESSON_DIR = path.join(ROOT, "prep/lessons/v1");
const ITEM_META = { prov: "SMD", gen: "hand", set: "maikbook2", d: 1, cog: "recall", credit: "StewardMD original medical knowledge base", licence: "CC BY 4.0 (StewardMD original)", licenceStandard: "CC BY 4.0", licenseUrl: "https://creativecommons.org/licenses/by/4.0", quality: { status: "automated_checks_passed", gates: { author_self_check: { note: "Author-verified against standard peer references" } } } };
fs.mkdirSync(SUBJECT_DIR, { recursive: true });
const seenIds = new Set();
const seenStems = new Set();
let failures = 0, ovWritten = 0, kbWritten = 0, kbSkipped = 0;
const ansDist = [0, 0, 0, 0];
for (const m of M) {
  if (m.mcqs.length !== 10) { console.error("COUNT", m.id, m.mcqs.length); failures++; }
  const lf = path.join(LESSON_DIR, m.id + ".json");
  if (!fs.existsSync(lf)) { console.error("NOLesson", m.id); failures++; }
  for (const q of m.mcqs) {
    if (seenIds.has(q.id)) { console.error("DUPID", q.id); failures++; }
    seenIds.add(q.id);
    const stemKey = q.q.toLowerCase().replace(/[^a-z ]/g, "");
    if (seenStems.has(stemKey)) { console.error("DUPSTEM", q.id); failures++; }
    seenStems.add(stemKey);
    if (!(q.q && q.q.length > 20 && q.o.length === 4 && q.a >= 0 && q.a < 4 && q.exp && q.exp.length > 20 && q.r.length === 4 && q.kp && q.kp.length > 5)) { console.error("MCQSHAPE", m.id, q.id); failures++; }
    if (/mg\b|milligram|mcg|microgram|\b\d+\s*(mg|g|ml|units?)\b/i.test(q.q + " " + q.exp)) { console.error("DOSE", m.id, q.id); failures++; }
  }
  const items = m.mcqs.map((q, i) => {
    const rot = (arr, k) => arr.map((_, j) => arr[(j + k) % arr.length]);
    const r = (i + M.indexOf(m) + 11) % 4;
    ansDist[(q.a - r + 4) % 4]++;
    return { ...ITEM_META, ...q, o: rot(q.o, r), r: rot(q.r, r), a: (q.a - r + 4) % 4, topic: m.id };
  });
  for (const it of items) {
    if (!(it.o.length === 4 && it.a >= 0 && it.a < 4 && it.r.length === 4)) { console.error("ROT", m.id, it.id); failures++; }
  }
  fs.writeFileSync(path.join(SUBJECT_DIR, m.id + ".json"), JSON.stringify({ topic: m.id, set: "maikbook2", v: 1, items }, null, 2) + "\n");
  ovWritten++;
}
for (const k of KB) {
  if (k.id !== k.file.replace(/\.json$/, "")) { console.error("KBID", k.file); failures++; }
  if (!(k.name && k.name.length > 5 && k.aliases.length >= 4 && k.pearls.length >= 4 && k.patho.length > 50 && k.diffs.length >= 4 && k.invs.length >= 4)) { console.error("KBSHAPE", k.file); failures++; }
  const kbPath = path.join(KB_DIR, k.file);
  if (!fs.existsSync(kbPath)) {
    fs.writeFileSync(kbPath, JSON.stringify({ id: k.id, name: k.name, aliases: [...k.aliases], class: "non_infective", system: "Skin / Dermatology", specialty: "Dermatology", referenceOnly: true, review: { status: "ai_drafted", reviewedBy: null, reviewedAt: null, clinicianApproved: false }, reference: { source: REF, sourceEdition: "Khanna primary + Fitzpatrick 8ed depth (2026-10-14)", pages: null, clinicalPearls: [...k.pearls, ...k.approach], pathophysiology: k.patho, additionalDifferentials: [...k.diffs], additionalInvestigations: [...k.invs] } }, null, 2) + "\n");
    kbWritten++;
  } else kbSkipped++;
}
